let note=0;const notes=['The best ideas don’t just ask for attention.\nThey give you a reason to stay.','Start with curiosity.\nKeep the happy accidents.\nMake every line mean something.','A good image tells a story.\nA great one leaves a little room\nfor your own.'];function changeNote(d){note=(note+d+notes.length)%notes.length;$('#note-text').textContent=notes[note];$('#note-text').style.whiteSpace='pre-line';$('#note-count').textContent=`0${note+1} / 03`;$$('.note-dots i').forEach((e,i)=>e.classList.toggle('active',i===note))}$$('.note-controls button')[0].onclick=()=>changeNote(-1);$$('.note-controls button')[1].onclick=()=>changeNote(1);$('.quote-area').onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();changeNote(e.key==='ArrowRight'?1:-1)}};let noteX;$('.quote-area').onpointerdown=e=>noteX=e.clientX;$('.quote-area').onpointerup=e=>{if(noteX!==undefined&&Math.abs(e.clientX-noteX)>40)changeNote(e.clientX<noteX?1:-1);noteX=undefined};
