function caseMarkup(p){const next=projects[(projects.indexOf(p)+1)%projects.length];return `<header class="case-header"><span class="eyebrow">PROJECT ${p.no} / INDEPENDENT CONCEPT / 2026</span><h2 id="case-title">${p.name}<span>.</span></h2><p>${p.category} — ${p.credit}</p></header><img class="case-cover" src="assets/${p.image}" alt="${p.name} final artwork"><div class="case-body"><div><h3>01 / THE CHALLENGE</h3><p>${p.idea}</p></div><div><h3>02 / THE IDEA</h3><p>${p.desc} The visual begins with one clear motif and builds the story around it.</p></div><div><h3>03 / CREATIVE DIRECTION</h3><p>${p.direction}</p></div><div><h3>04 / THE PROCESS</h3><p>${p.process}</p></div><div><h3>05 / FINAL OUTPUT</h3><p>${p.result}</p></div><div><h3>06 / THE RESULT</h3><p>A completed independent visual exploration. No client campaign or performance metrics are claimed for this concept.</p></div></div><a class="case-next" href="?project=${next.id}" data-project="${next.id}">Next project / <span>${next.name} ↗</span></a>`}
function openProject(id,push=true){const p=projects.find(p=>p.id===id);if(!p)return;if(!caseDialog.open){caseOrigin=document.activeElement;previousUrl=location.pathname+location.hash;caseDialog.showModal();document.body.style.overflow='hidden'}$('#case-content').innerHTML=caseMarkup(p);caseDialog.scrollTop=0;document.title=p.name+' — Rama Studio';if(push)history.pushState({project:id},'',`?project=${id}`)}
