let step=0;const form=$('#inquiry-form');function validStep(){const inputs=$$('input,textarea,select', $(`[data-form-step="${step}"]`));for(const input of inputs){if(!input.checkValidity()){input.reportValidity();return false}}return true}function formData(){return Object.fromEntries(new FormData(form))}function showStep(){const fields=$$('.form-step');fields.forEach((e,i)=>e.hidden=i!==step);$('#form-count').textContent=`0${step+1} / 04`;$('.form-progress i').style.width=(step+1)*25+'%';$('#form-back').hidden=step===0;$('#form-next').hidden=step===3;$('#form-submit').hidden=step!==3;$('#form-status').textContent='';if(step===3){const d=formData(),dl=document.createElement('dl');Object.entries({Service:d.service,Idea:d.idea,Budget:d.budget,Timeline:d.timeline,Name:d.name,Email:d.email,...(d.phone?{Phone:d.phone}:{})}).forEach(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dl.append(dt,dd)});$('#brief-review').replaceChildren(dl)}const target=fields[step].querySelector('h3');target.tabIndex=-1;target.focus({preventScroll:true})}
$('#form-next').onclick=()=>{if(validStep()){step++;showStep()}};$('#form-back').onclick=()=>{step=Math.max(0,step-1);showStep()};form.onkeydown=e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT'&&step<3){e.preventDefault();$('#form-next').click()}};form.onsubmit=e=>{e.preventDefault();if(step!==3)return;const d=formData();const brief=`RAMA STUDIO — PROJECT INQUIRY\n\nService: ${d.service}\n\nThe idea:\n${d.idea}\n\nBudget: ${d.budget}\nTimeline: ${d.timeline}\nName: ${d.name}\nEmail: ${d.email}\nPhone: ${d.phone||'Not provided'}\n\nThis brief has not been sent. Share it directly with the studio once contact details are available.\n`;const u=URL.createObjectURL(new Blob([brief],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='rama-studio-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('#form-status').textContent='Your brief is ready. Download started — nothing has been sent.'};
